     1→import { useState, useCallback, useMemo } from "react";
     2→import type {
     3→  ActionFunctionArgs,
     4→  HeadersFunction,
     5→  LoaderFunctionArgs,
     6→} from "react-router";
     7→import { useFetcher, useLoaderData, useNavigate } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { authenticate } from "../shopify.server";
    10→import { boundary } from "@shopify/shopify-app-react-router/server";
    11→import db from "../db.server";
    12→import { getShopSubscription } from "../billing.server";
    13→import { PLAN_LIMITS } from "../plans";
    14→import {
    15→  Page,
    16→  Layout,
    17→  Card,
    18→  TextField,
    19→  Button,
    20→  Banner,
    21→  BlockStack,
    22→  InlineStack,
    23→  Text,
    24→  Badge,
    25→  DataTable,
    26→  Modal,
    27→  Select,
    28→  Divider,
    29→  EmptyState,
    30→  Box,
    31→  Icon,
    32→  Tooltip,
    33→  DropZone,
    34→  Pagination,
    35→} from "@shopify/polaris";
    36→import {
    37→  SearchIcon,
    38→  DeleteIcon,
    39→  PlusIcon,
    40→  StarIcon,
    41→  ImportIcon,
    42→  ExportIcon,
    43→} from "@shopify/polaris-icons";
    44→
    45→const PAGE_SIZE = 10;
    46→
    47→export const loader = async ({ request }: LoaderFunctionArgs) => {
    48→  const { session } = await authenticate.admin(request);
    49→  const shop = session.shop;
    50→
    51→  const [zipCodes, subscription] = await Promise.all([
    52→    db.zipCode.findMany({
    53→      where: { shop },
    54→      orderBy: { createdAt: "desc" },
    55→    }),
    56→    getShopSubscription(shop),
    57→  ]);
    58→
    59→  const stats = {
    60→    total: zipCodes.length,
    61→    allowed: zipCodes.filter((z) => z.type === "allowed").length,
    62→    blocked: zipCodes.filter((z) => z.type === "blocked").length,
    63→    active: zipCodes.filter((z) => z.isActive).length,
    64→  };
    65→
    66→  return { zipCodes, stats, subscription };
    67→};
    68→
    69→export const action = async ({ request }: ActionFunctionArgs) => {
    70→  const { session } = await authenticate.admin(request);
    71→  const shop = session.shop;
    72→  const formData = await request.formData();
    73→  const intent = formData.get("intent");
    74→
    75→  if (intent === "add") {
    76→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
    77→    const label = String(formData.get("label") || "").trim();
    78→    const zone = String(formData.get("zone") || "").trim();
    79→    const message = String(formData.get("message") || "").trim();
    80→    const eta = String(formData.get("eta") || "").trim();
    81→    const type = String(formData.get("type") || "allowed");
    82→
    83→    if (!zipCode) return { error: "Zip code is required." };
    84→
    85→    const subscription = await getShopSubscription(shop);
    86→    const limits = PLAN_LIMITS[subscription.planTier];
    87→
    88→    if (type === "blocked" && !limits.allowBlocked) {
    89→      return {
    90→        error:
    91→          "Blocked zip codes are not available on the Free plan. Upgrade to Pro or Ultimate.",
    92→        upgradeRequired: true,
    93→      };
    94→    }
    95→
    96→    const currentCount = await db.zipCode.count({ where: { shop } });
    97→    if (limits.maxZipCodes !== Infinity && currentCount >= limits.maxZipCodes) {
    98→      return {
    99→        error: `You have reached the ${limits.maxZipCodes} zip code limit for the Free plan. Upgrade to Pro for unlimited zip codes.`,
   100→        upgradeRequired: true,
   101→      };
   102→    }
   103→
   104→    try {
   105→      await db.zipCode.create({
   106→        data: {
   107→          shop,
   108→          zipCode,
   109→          label: label || null,
   110→          zone: zone || null,
   111→          message: message || null,
   112→          eta: eta || null,
   113→          type,
   114→        },
   115→      });
   116→      return { success: true, action: "added", zipCode };
   117→    } catch {
   118→      return { error: `Zip code "${zipCode}" already exists.` };
   119→    }
   120→  }
   121→
   122→  if (intent === "delete") {
   123→    const id = String(formData.get("id"));
   124→    await db.zipCode.delete({ where: { id } });
   125→    return { success: true, action: "deleted" };
   126→  }
   127→
   128→  if (intent === "toggle") {
   129→    const id = String(formData.get("id"));
   130→    const isActive = formData.get("isActive") === "true";
   131→    await db.zipCode.update({
   132→      where: { id },
   133→      data: { isActive: !isActive },
   134→    });
   135→    return { success: true, action: "toggled" };
   136→  }
   137→
   138→  if (intent === "check") {
   139→    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
   140→    const found = await db.zipCode.findUnique({
   141→      where: { shop_zipCode: { shop, zipCode } },
   142→    });
   143→    if (!found) return { checkResult: { found: false, zipCode } };
   144→    return { checkResult: { found: true, zipCode, record: found } };
   145→  }
   146→
   147→  if (intent === "bulk-import") {
   148→    const csvData = String(formData.get("csvData") || "");
   149→    if (!csvData.trim()) return { error: "No CSV data provided." };
   150→
   151→    const subscription = await getShopSubscription(shop);
   152→    const limits = PLAN_LIMITS[subscription.planTier];
   153→
   154→    const lines = csvData
   155→      .split("\n")
   156→      .map((l) => l.trim())
   157→      .filter((l) => l.length > 0);
   158→
   159→    // Skip header row if present
   160→    const startIdx =
   161→      lines.length > 0 &&
   162→      lines[0].toLowerCase().includes("zip")
   163→        ? 1
   164→        : 0;
   165→
   166→    const currentCount = await db.zipCode.count({ where: { shop } });
   167→    let imported = 0;
   168→    let skipped = 0;
   169→    const errors: string[] = [];
   170→
   171→    for (let i = startIdx; i < lines.length; i++) {
   172→      const cols = lines[i].split(",").map((c) => c.trim().replace(/^"|"$/g, ""));
   173→      const zipCode = (cols[0] || "").toUpperCase();
   174→      if (!zipCode) continue;
   175→
   176→      const zone = cols[1] || null;
   177→      const type = (cols[2] || "allowed").toLowerCase() === "blocked" ? "blocked" : "allowed";
   178→      const message = cols[3] || null;
   179→      const eta = cols[4] || null;
   180→
   181→      if (type === "blocked" && !limits.allowBlocked) {
   182→        skipped++;
   183→        continue;
   184→      }
   185→
   186→      if (
   187→        limits.maxZipCodes !== Infinity &&
   188→        currentCount + imported >= limits.maxZipCodes
   189→      ) {
   190→        errors.push(
   191→          `Reached the ${limits.maxZipCodes} zip code limit. ${lines.length - startIdx - imported - skipped} zip codes were not imported.`,
   192→        );
   193→        break;
   194→      }
   195→
   196→      try {
   197→        await db.zipCode.upsert({
   198→          where: { shop_zipCode: { shop, zipCode } },
   199→          create: {
   200→            shop,
   201→            zipCode,
   202→            zone,
   203→            type,
   204→            message,
   205→            eta,
   206→          },
   207→          update: {
   208→            zone: zone ?? undefined,
   209→            type,
   210→            message: message ?? undefined,
   211→            eta: eta ?? undefined,
   212→          },
   213→        });
   214→        imported++;
   215→      } catch {
   216→        skipped++;
   217→      }
   218→    }
   219→
   220→    return {
   221→      success: true,
   222→      action: "bulk-import",
   223→      imported,
   224→      skipped,
   225→      errors,
   226→    };
   227→  }
   228→
   229→  if (intent === "export") {
   230→    const zipCodes = await db.zipCode.findMany({
   231→      where: { shop },
   232→      orderBy: { createdAt: "desc" },
   233→    });
   234→
   235→    const header = "Zip Code,Zone,Status,Message,ETA,Active";
   236→    const rows = zipCodes.map(
   237→      (z) =>
   238→        `"${z.zipCode}","${z.zone || ""}","${z.type}","${z.message || ""}","${z.eta || ""}","${z.isActive ? "Yes" : "No"}"`,
   239→    );
   240→    const csv = [header, ...rows].join("\n");
   241→
   242→    return { success: true, action: "export", csv };
   243→  }
   244→
   245→  return null;
   246→};
   247→
   248→type ZipCodeRecord = {
   249→  id: string;
   250→  zipCode: string;
   251→  label: string | null;
   252→  zone: string | null;
   253→  message: string | null;
   254→  eta: string | null;
   255→  type: string;
   256→  isActive: boolean;
   257→  createdAt: string | Date;
   258→};
   259→
   260→export default function ZipCodeCheckerPage() {
   261→  const { zipCodes, stats, subscription } = useLoaderData<typeof loader>();
   262→  const fetcher = useFetcher<typeof action>();
   263→  const shopify = useAppBridge();
   264→  const navigate = useNavigate();
   265→
   266→  const limits = PLAN_LIMITS[subscription.planTier];
   267→  const isFreePlan = subscription.planTier === "free";
   268→  const atZipLimit =
   269→    limits.maxZipCodes !== Infinity && stats.total >= limits.maxZipCodes;
   270→
   271→  // Search & filter state
   272→  const [searchQuery, setSearchQuery] = useState("");
   273→  const [statusFilter, setStatusFilter] = useState("all");
   274→  const [currentPage, setCurrentPage] = useState(1);
   275→
   276→  // Check zip code state
   277→  const [checkZip, setCheckZip] = useState("");
   278→
   279→  // Add modal state
   280→  const [addModalOpen, setAddModalOpen] = useState(false);
   281→  const [newZip, setNewZip] = useState("");
   282→  const [newLabel, setNewLabel] = useState("");
   283→  const [newZone, setNewZone] = useState("");
   284→  const [newMessage, setNewMessage] = useState("");
   285→  const [newEta, setNewEta] = useState("");
   286→  const [newType, setNewType] = useState("allowed");
   287→
   288→  // Import modal state
   289→  const [importModalOpen, setImportModalOpen] = useState(false);
   290→  const [csvText, setCsvText] = useState("");
   291→  const [importFile, setImportFile] = useState<File | null>(null);
   292→
   293→  const isCheckLoading =
   294→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "check";
   295→  const isAddLoading =
   296→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "add";
   297→  const isImportLoading =
   298→    fetcher.state !== "idle" &&
   299→    fetcher.formData?.get("intent") === "bulk-import";
   300→
   301→  const checkResult =
   302→    fetcher.data && "checkResult" in fetcher.data
   303→      ? fetcher.data.checkResult
   304→      : null;
   305→  const actionError =
   306→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
   307→  const upgradeRequired =
   308→    fetcher.data && "upgradeRequired" in fetcher.data
   309→      ? fetcher.data.upgradeRequired
   310→      : false;
   311→  const importResult =
   312→    fetcher.data &&
   313→    "action" in fetcher.data &&
   314→    fetcher.data.action === "bulk-import"
   315→      ? fetcher.data
   316→      : null;
   317→
   318→  // Filtered zip codes
   319→  const filteredZipCodes = useMemo(() => {
   320→    let filtered = zipCodes as ZipCodeRecord[];
   321→
   322→    if (searchQuery.trim()) {
   323→      const q = searchQuery.trim().toLowerCase();
   324→      filtered = filtered.filter(
   325→        (z) =>
   326→          z.zipCode.toLowerCase().includes(q) ||
   327→          (z.zone && z.zone.toLowerCase().includes(q)) ||
   328→          (z.label && z.label.toLowerCase().includes(q)) ||
   329→          (z.message && z.message.toLowerCase().includes(q)),
   330→      );
   331→    }
   332→
   333→    if (statusFilter === "allowed") {
   334→      filtered = filtered.filter((z) => z.type === "allowed");
   335→    } else if (statusFilter === "blocked") {
   336→      filtered = filtered.filter((z) => z.type === "blocked");
   337→    }
   338→
   339→    return filtered;
   340→  }, [zipCodes, searchQuery, statusFilter]);
   341→
   342→  // Pagination
   343→  const totalPages = Math.max(1, Math.ceil(filteredZipCodes.length / PAGE_SIZE));
   344→  const paginatedZipCodes = useMemo(() => {
   345→    const start = (currentPage - 1) * PAGE_SIZE;
   346→    return filteredZipCodes.slice(start, start + PAGE_SIZE);
   347→  }, [filteredZipCodes, currentPage]);
   348→
   349→  // Reset to page 1 when search/filter changes
   350→  const handleSearchChange = useCallback((val: string) => {
   351→    setSearchQuery(val);
   352→    setCurrentPage(1);
   353→  }, []);
   354→
   355→  const handleFilterChange = useCallback((val: string) => {
   356→    setStatusFilter(val);
   357→    setCurrentPage(1);
   358→  }, []);
   359→
   360→  const handleCheck = useCallback(() => {
   361→    if (!checkZip.trim()) return;
   362→    const fd = new FormData();
   363→    fd.set("intent", "check");
   364→    fd.set("checkZip", checkZip);
   365→    fetcher.submit(fd, { method: "POST" });
   366→  }, [checkZip, fetcher]);
   367→
   368→  const handleAdd = useCallback(() => {
   369→    if (!newZip.trim()) return;
   370→    const fd = new FormData();
   371→    fd.set("intent", "add");
   372→    fd.set("zipCode", newZip);
   373→    fd.set("label", newLabel);
   374→    fd.set("zone", newZone);
   375→    fd.set("message", newMessage);
   376→    fd.set("eta", newEta);
   377→    fd.set("type", newType);
   378→    fetcher.submit(fd, { method: "POST" });
   379→    if (!actionError) {
   380→      setNewZip("");
   381→      setNewLabel("");
   382→      setNewZone("");
   383→      setNewMessage("");
   384→      setNewEta("");
   385→      setNewType("allowed");
   386→      setAddModalOpen(false);
   387→    }
   388→  }, [newZip, newLabel, newZone, newMessage, newEta, newType, fetcher, actionError]);
   389→
   390→  const handleDelete = useCallback(
   391→    (id: string) => {
   392→      const fd = new FormData();
   393→      fd.set("intent", "delete");
   394→      fd.set("id", id);
   395→      fetcher.submit(fd, { method: "POST" });
   396→      shopify.toast.show("Zip code removed");
   397→    },
   398→    [fetcher, shopify],
   399→  );
   400→
   401→  const handleToggle = useCallback(
   402→    (id: string, isActive: boolean) => {
   403→      const fd = new FormData();
   404→      fd.set("intent", "toggle");
   405→      fd.set("id", id);
   406→      fd.set("isActive", String(isActive));
   407→      fetcher.submit(fd, { method: "POST" });
   408→    },
   409→    [fetcher],
   410→  );
   411→
   412→  const handleImport = useCallback(() => {
   413→    const dataToImport = csvText.trim();
   414→    if (!dataToImport) return;
   415→    const fd = new FormData();
   416→    fd.set("intent", "bulk-import");
   417→    fd.set("csvData", dataToImport);
   418→    fetcher.submit(fd, { method: "POST" });
   419→  }, [csvText, fetcher]);
   420→
   421→  const handleFileUpload = useCallback(
   422→    (_files: File[], acceptedFiles: File[]) => {
   423→      if (acceptedFiles.length > 0) {
   424→        const file = acceptedFiles[0];
   425→        setImportFile(file);
   426→        const reader = new FileReader();
   427→        reader.onload = (e) => {
   428→          const text = e.target?.result;
   429→          if (typeof text === "string") {
   430→            setCsvText(text);
   431→          }
   432→        };
   433→        reader.readAsText(file);
   434→      }
   435→    },
   436→    [],
   437→  );
   438→
   439→  const handleExport = useCallback(() => {
   440→    const fd = new FormData();
   441→    fd.set("intent", "export");
   442→    fetcher.submit(fd, { method: "POST" });
   443→  }, [fetcher]);
   444→
   445→  // Trigger download when export data arrives
   446→  const exportCsv =
   447→    fetcher.data &&
   448→    "action" in fetcher.data &&
   449→    fetcher.data.action === "export" &&
   450→    "csv" in fetcher.data
   451→      ? (fetcher.data.csv as string)
   452→      : null;
   453→
   454→  if (exportCsv) {
   455→    const blob = new Blob([exportCsv], { type: "text/csv" });
   456→    const url = URL.createObjectURL(blob);
   457→    const a = document.createElement("a");
   458→    a.href = url;
   459→    a.download = "zip-codes.csv";
   460→    a.click();
   461→    URL.revokeObjectURL(url);
   462→  }
   463→
   464→  const typeOptions = [
   465→    { label: "Allowed — permit this zip code", value: "allowed" },
   466→    ...(limits.allowBlocked
   467→      ? [{ label: "Blocked — deny this zip code", value: "blocked" }]
   468→      : []),
   469→  ];
   470→
   471→  const filterOptions = [
   472→    { label: "All", value: "all" },
   473→    { label: "Allowed", value: "allowed" },
   474→    { label: "Blocked", value: "blocked" },
   475→  ];
   476→
   477→  const tableRows = paginatedZipCodes.map((z) => [
   478→    <Text as="span" fontWeight="bold" key={`zip-${z.id}`}>
   479→      {z.zipCode}
   480→    </Text>,
   481→    z.zone || (
   482→      <Text as="span" tone="subdued">
   483→        —
   484→      </Text>
   485→    ),
   486→    <InlineStack gap="300" blockAlign="center" key={`status-${z.id}`}>
   487→      <button
   488→        onClick={() => handleToggle(z.id, z.isActive)}
   489→        style={{
   490→          width: "44px",
   491→          height: "24px",
   492→          borderRadius: "12px",
   493→          border: "none",
   494→          cursor: "pointer",
   495→          position: "relative",
   496→          backgroundColor: z.isActive ? "#2e7d32" : "#ccc",
   497→          transition: "background-color 0.2s",
   498→          padding: 0,
   499→        }}
   500→        aria-label={z.isActive ? "Deactivate" : "Activate"}
   501→      >
   502→        <span
   503→          style={{
   504→            position: "absolute",
   505→            top: "2px",
   506→            left: z.isActive ? "22px" : "2px",
   507→            width: "20px",
   508→            height: "20px",
   509→            borderRadius: "50%",
   510→            backgroundColor: "#fff",
   511→            transition: "left 0.2s",
   512→            boxShadow: "0 1px 3px rgba(0,0,0,0.3)",
   513→          }}
   514→        />
   515→      </button>
   516→      <Badge tone={z.type === "allowed" ? "success" : "critical"}>
   517→        {z.type === "allowed" ? "Allow" : "Block"}
   518→      </Badge>
   519→    </InlineStack>,
   520→    z.message || (
   521→      <Text as="span" tone="subdued">
   522→        —
   523→      </Text>
   524→    ),
   525→    z.eta || (
   526→      <Text as="span" tone="subdued">
   527→        —
   528→      </Text>
   529→    ),
   530→    <Tooltip content="Delete zip code" key={`del-${z.id}`}>
   531→      <Button
   532→        size="slim"
   533→        tone="critical"
   534→        variant="tertiary"
   535→        onClick={() => handleDelete(z.id)}
   536→        icon={DeleteIcon}
   537→        accessibilityLabel="Delete"
   538→      />
   539→    </Tooltip>,
   540→  ]);
   541→
   542→  return (
   543→    <Page
   544→      title="Zip Code Checker"
   545→      subtitle="Manage allowed and blocked zip codes for your store"
   546→      primaryAction={
   547→        atZipLimit
   548→          ? {
   549→              content: "Upgrade Plan",
   550→              icon: StarIcon,
   551→              onAction: () => navigate("/app/pricing"),
   552→            }
   553→          : {
   554→              content: "Add Zip Code",
   555→              icon: PlusIcon,
   556→              onAction: () => setAddModalOpen(true),
   557→            }
   558→      }
   559→    >
   560→      <Box paddingBlockEnd="1600">
   561→      <Layout>
   562→        {/* Upgrade banner for free plan */}
   563→        {isFreePlan && (
   564→          <Layout.Section>
   565→            <Banner
   566→              title="Unlock unlimited zip codes & blocked zones"
   567→              tone="info"
   568→              action={{
   569→                content: "Upgrade to Pro",
   570→                onAction: () => navigate("/app/pricing"),
   571→              }}
   572→              secondaryAction={{
   573→                content: "See all plans",
   574→                onAction: () => navigate("/app/pricing"),
   575→              }}
   576→            >
   577→              <Text as="p" variant="bodyMd">
   578→                You&apos;re on the Free plan — limited to{" "}
   579→                {limits.maxZipCodes} allowed zip codes only. Pro unlocks
   580→                unlimited zip codes, blocked zones, delivery rules, and more.
   581→              </Text>
   582→            </Banner>
   583→          </Layout.Section>
   584→        )}
   585→
   586→        {/* Zip limit warning */}
   587→        {atZipLimit && (
   588→          <Layout.Section>
   589→            <Banner
   590→              title="Zip code limit reached"
   591→              tone="warning"
   592→              action={{
   593→                content: "Upgrade to Pro",
   594→                onAction: () => navigate("/app/pricing"),
   595→              }}
   596→            >
   597→              You have reached the {limits.maxZipCodes} zip code limit for the
   598→              Free plan. Upgrade to Pro for unlimited zip codes.
   599→            </Banner>
   600→          </Layout.Section>
   601→        )}
   602→
   603→        {/* Stats Row */}
   604→        <Layout.Section>
   605→          <InlineStack gap="400" wrap>
   606→            {/* Total */}
   607→            <Box
   608→              padding="400"
   609→              background="bg-surface"
   610→              borderWidth="025"
   611→              borderColor="border"
   612→              borderRadius="200"
   613→              minWidth="160px"
   614→            >
   615→              <BlockStack gap="150">
   616→                <Text as="p" tone="subdued" variant="bodySm">
   617→                  Total Zip Codes
   618→                </Text>
   619→                <InlineStack gap="150" blockAlign="center">
   620→                  <Text as="p" variant="headingXl" fontWeight="bold">
   621→                    {stats.total}
   622→                  </Text>
   623→                  {limits.maxZipCodes !== Infinity && (
   624→                    <Text as="p" tone="subdued" variant="bodySm">
   625→                      / {limits.maxZipCodes}
