const handleOpenEdit = useCallback((z: ZipCodeRecord) => {
  setEditId(z.id);
  setEditZip(z.zipCode);
  setEditLabel(z.label || "");
  setEditZone(z.zone || "");
  setEditMessage(z.message || "");
  setEditEta(z.eta || "");
